-- Populate empty legal JSON from the legal copy shipped with the app.
update public.admin_app_settings
set value = jsonb_set(
  jsonb_set(
    value, '{terms}',
    case when jsonb_array_length(coalesce(value->'terms', '[]'::jsonb)) = 0 then $legal$[{"heading":"1. Objet et Éditeur","paragraphs":["Les présentes conditions générales d'utilisation (« CGU ») régissent l'accès et l'utilisation de l'application Geno (« l'Application »), éditée par la société Geno Togo (« l'Éditeur »). Contact : legal@geno.app.","En créant un compte et en utilisant l'Application, vous reconnaissez avoir lu et accepté les présentes CGU sans réserve."]},{"heading":"2. Éligibilité et avertissement médical","paragraphs":["L'Application est strictement réservée aux personnes majeures. En créant un compte, vous certifiez sur l'honneur avoir au moins 18 ans révolus.","Avertissement important : Geno est un service de mise en relation sociale et amoureuse. L'Application ne constitue en aucun cas un service médical, un laboratoire d'analyses, ni un conseil en génétique ou en santé. Les informations affichées sur les profils (notamment les marqueurs de compatibilité déclarés comme le statut vis-à-vis de la drépanocytose) sont purement déclaratives et partagées volontairement par les utilisateurs. Elles ne remplacent en aucun cas un examen médical ou l'avis d'un professionnel de santé."]},{"heading":"3. Création et sécurité du compte","paragraphs":["La création d'un compte nécessite la fourniture d'informations exactes, sincères et à jour (notamment une adresse e-mail valide). Vous êtes seul responsable de la confidentialité de vos identifiants et de toute activité effectuée depuis votre compte.","Un compte est strictement personnel : il ne peut être cédé, prêté ni vendu. Vous ne pouvez détenir qu'un seul compte actif sur la plateforme."]},{"heading":"4. Comportement attendu et modération","paragraphs":["Geno promeut des échanges bienveillants et respectueux. Sont strictement interdits : tout propos ou contenu à caractère harcelant, haineux, discriminatoire, menaçant, pornographique, pédopornographique ou illégal ; l'usurpation d'identité ; le spamming ; la publicité non sollicitée et la publication de photos de personnes mineures.","Toute publication de nudité, d'actes explicites ou toute tentative de contournement des filtres de modération automatique entraînera la suspension immédiate et définitive du compte, sans préavis."]},{"heading":"5. Vérification des profils et sécurité","paragraphs":["Afin de garantir un environnement sûr et de lutter contre les faux comptes, Geno met en place un système de vérification d'identité ainsi qu'une modération hybride (automatisée et humaine).","Vous disposez à tout moment de la possibilité de bloquer et de signaler un utilisateur depuis son profil ou la discussion. Un profil bloqué ne pourra plus interagir avec vous ni apparaître dans votre fil de découverte."]},{"heading":"6. Suppression et résiliation","paragraphs":["Vous pouvez supprimer votre compte à tout moment directement depuis l'application via Profil > Sécurité et confidentialité. Cette action est immédiate et irréversible : profil, photos, matchs et messages seront définitivement supprimés.","L'Éditeur se réserve le droit de suspendre ou de résilier l'accès d'un utilisateur à l'Application sans préavis en cas de violation des présentes CGU ou d'atteinte à la sécurité de la communauté."]},{"heading":"7. Limites de responsabilité","paragraphs":["L'Éditeur met en œuvre tous les moyens raisonnables pour assurer la disponibilité et la sécurité de l'Application. Toutefois, Geno ne garantit pas une continuité de service ininterrompue ni le succès des rencontres initiées.","Les échanges et rencontres en personne se font sous la responsabilité exclusive des utilisateurs. L'Éditeur ne saurait être tenu responsable du comportement des utilisateurs en dehors ou au sein de l'Application."]},{"heading":"8. Droit applicable et contact","paragraphs":["Les présentes CGU sont régies et interprétées conformément aux lois en vigueur au Togo. En cas de litige, les parties s'engagent à rechercher une solution amiable prioritaire avant toute action judiciaire.","Pour toute question juridique ou signalement spécifique : legal@geno.app ou contact@geno.app."]}]$legal$::jsonb else value->'terms' end
  ), '{privacy}',
  case when jsonb_array_length(coalesce(value->'privacy', '[]'::jsonb)) = 0 then $legal$[{"heading":"1. Responsable de traitement","paragraphs":["Le responsable du traitement des données est la société Geno Togo. Contact DPO / Confidentialité : privacy@geno.app."]},{"heading":"2. Données collectées","paragraphs":["Compte : adresse e-mail, mot de passe (haché), identifiant unique.","Profil : prénom, âge, ville, bio, centres d'intérêt, photos, et les informations de compatibilité que vous renseignez volontairement, y compris vos marqueurs de santé déclarés (par exemple le statut vis-à-vis de la drépanocytose).","Utilisation : matchs, likes, messages échangés, signalements et blocages, interactions avec les conseils de coaching.","Technique : identifiants de notification push (sans données de localisation fine), journaux de connexion.","Aucune donnée de géolocalisation précise n'est collectée : la localisation est limitée à la ville déclarée."]},{"heading":"3. Finalités","paragraphs":["Fournir le service de rencontres (matching, messagerie) ; assurer la sécurité de la plateforme (modération, détection de faux profils) ; envoyer les notifications liées aux matchs et messages ; améliorer l'expérience utilisateur.","Vos marqueurs de santé ne sont visibles que par les personnes avec qui vous avez un match, et uniquement si vous avez choisi de les renseigner."]},{"heading":"4. Base légale","paragraphs":["Exécution du contrat (création de compte et utilisation du service) ; consentement explicite pour les données de santé déclarées et les notifications push ; intérêt légitime pour la sécurité et la modération."]},{"heading":"5. Partage et hébergement","paragraphs":["Les données sont hébergées par Supabase (serveurs certifiés, chiffrement en transit et au repos). Les notifications push transitent par les services Apple (APNs) et Google (FCM).","Aucune donnée personnelle n'est vendue ni louée à des tiers à des fins publicitaires."]},{"heading":"6. Conservation","paragraphs":["Les données sont conservées pendant la durée d'utilisation du compte, puis supprimées (ou anonymisées) lors de la suppression du compte, action réalisable depuis Profil > Sécurité et confidentialité.","Les journaux techniques sont conservés au maximum 12 mois."]},{"heading":"7. Sécurité","paragraphs":["Contrôle d'accès aux données au niveau base (Row Level Security), authentification par jeton, chiffrement TLS des échanges, service role jamais exposé côté client.","La vérification d'identité est traitée par un prestataire spécialisé ; les documents fournis ne sont pas conservés au-delà du temps nécessaire au contrôle."]},{"heading":"8. Vos droits","paragraphs":["Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et de portabilité de vos données, ainsi que d'un droit d'opposition. Exercez-les depuis Profil > Sécurité et confidentialité (suppression directe) ou par e-mail à privacy@geno.app.","Vous pouvez également introduire une réclamation auprès de l'autorité de protection des données compétente (ex: IPDCP au Togo ou la CNIL en France)."]},{"heading":"9. Contact","paragraphs":["Pour toute question relative à la confidentialité ou à la protection de vos données : privacy@geno.app."]}]$legal$::jsonb else value->'privacy' end
), updated_at = now()
where setting_key = 'legal_content'
  and (jsonb_array_length(coalesce(value->'terms', '[]'::jsonb)) = 0 or jsonb_array_length(coalesce(value->'privacy', '[]'::jsonb)) = 0);
